var stoneGameVIII = function(stones) {
    const n = stones.length;
    const pref = Array(n);
    pref[0] = stones[0];
    for (let i = 1; i < n; ++i) pref[i] = pref[i - 1] + stones[i];

    let dp = pref[n - 1];
    for (let i = n - 2; i >= 1; --i) {
        dp = Math.max(dp, pref[i] - dp);
    }
    return dp;
};
